INSERT INTO `currency_calculator_page` (`id`, `section`, `item_key`, `title`, `description`, `image`, `icon_svg`, `icon_class`, `color_scheme`, `badge_text`, `button_text`, `button_url`, `btn_text`, `subtitle`, `paragraphs`, `question`, `answer`, `name`, `avatar_url`, `rating`, `text_content`, `stat_value`, `stat_label`, `stat_suffix`, `logo_url`, `alt_text`, `list_items_text`, `check_list_text`, `extra_content`, `link`, `content`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES
(1, 'hero', 'hero_content', 'Currency Calculator', 'Just enter your Mobile Number, AWB tracking number or Order ID & it\'s done.', 'website_images/currency-calculator.webp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"title\":\"Currency <span class=\\\"moving-gradient-text\\\">Calculator<\\/span>\",\"description\":\"Just enter your Mobile Number, AWB tracking number or Order ID & it\'s done.\",\"image\":\"website_images\\/currency-calculator.webp\",\"link\":null,\"icon_svg\":null,\"icon_class\":null,\"color_class\":null,\"badge_text\":null,\"button_text\":null,\"button_url\":null,\"btn_text\":null,\"subtitle\":null,\"paragraphs\":null,\"question\":null,\"answer\":null,\"name\":null,\"avatar\":null,\"rating\":null,\"text\":null,\"value\":null,\"label\":null,\"suffix\":null,\"logo_url\":null,\"alt\":null}', 0, 'Active', '2026-05-17 07:26:04', '2026-05-26 10:55:58'),
(2, 'features', 'features_header', 'Role of Currency Converters in Global Transactions', 'Why do people use currency converter One of the most general reasons is the following: people may plan to move from one country to another, because of which they will be unable to use their domestic currency. So, the currencies may be converted due to the need of usage in other territories, where the domestic one may not be accepted. An online Currency Exchange Rate Conversion Calculator is good to use for business, personal, or educational purposes.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'Active', '2026-05-17 07:26:04', '2026-05-17 07:26:04'),
(3, 'features', 'feature_card_1', 'Real-time Exchange Rates', 'Get accurate and up-to-date currency exchange rates instantly for seamless global conversions.', NULL, 'fa-dollar-sign', NULL, 'feat-blue', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"icon\":\"fa-dollar-sign\",\"color_class\":\"feat-blue\"}', 2, 'Active', '2026-05-17 07:26:04', '2026-05-17 07:26:04'),
(4, 'features', 'feature_card_2', 'Reliable, Trusted & Secure', 'Our system ensures trusted data sources and secure calculations for dependable currency conversions.', NULL, 'fa-shield-alt', NULL, 'feat-purple', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"icon\":\"fa-shield-alt\",\"color_class\":\"feat-purple\"}', 3, 'Active', '2026-05-17 07:26:04', '2026-05-17 07:26:04'),
(5, 'features', 'feature_card_3', 'Instant Currencies Conversion', 'Convert currencies in seconds with fast processing and accurate results for any amount worldwide.', NULL, 'fa-exchange-alt', NULL, 'feat-green', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"icon\":\"fa-exchange-alt\",\"color_class\":\"feat-green\"}', 4, 'Active', '2026-05-17 07:26:04', '2026-05-17 07:26:04'),
(6, 'features', 'feature_card_4', 'Multi-Currency Support', 'Access a wide range of global currencies and convert between them easily for personal, business, or travel needs.', NULL, 'fa-globe', NULL, 'feat-orange', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"icon\":\"fa-globe\",\"color_class\":\"feat-orange\"}', 5, 'Active', '2026-05-17 07:26:04', '2026-05-17 07:26:04');
