INSERT INTO `ebook_page` (`id`, `section`, `item_key`, `title`, `description`, `image`, `icon_svg`, `icon_class`, `color_scheme`, `badge_text`, `button_text`, `button_url`, `btn_text`, `subtitle`, `paragraphs`, `question`, `answer`, `name`, `avatar_url`, `rating`, `text_content`, `stat_value`, `stat_label`, `stat_suffix`, `logo_url`, `alt_text`, `list_items_text`, `check_list_text`, `extra_content`, `link`, `content`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES
(1, NULL, NULL, 'Cross-Border trade & expansion opportunities', 'EThis eBook takes you on a tour of the current export landscape of India. Know about the global expansion opportunities for your eCommerce business.', 'website_images/book-1.webp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'Active', '2026-05-16 13:11:53', '2026-05-16 14:02:36'),
(2, NULL, NULL, 'Get started with hyperlocal delivery', 'The pandemic brought about a drastic shift in the buying process. People now shop online even for basic requirements. Learn about hyperlocal deliveries and how you can start with them.', 'website_images/book-3.webp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2, 'Active', '2026-05-16 13:11:53', '2026-05-16 13:11:53'),
(3, NULL, NULL, 'Master strategies for eCommerce business management', 'Get your hands on exclusive techniques and expert ideas about how to manage your eCommerce business efficiently.', 'website_images/book-2.webp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, 'Active', '2026-05-16 13:11:53', '2026-05-16 13:11:53'),
(4, 'hero', 'hero_content', 'eBooks for  <span class=\"moving-gradient-text\">Exporters</span>', NULL, 'website_images/e-books.webp', NULL, NULL, NULL, 'Read our ebooks', NULL, NULL, NULL, 'Must-read guides, handpicked for their popularity among global exporters', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"title\":\"Discover our most popular guides,<span class=\\\"moving-gradient-text\\\">carefully selected for global exporters<\\/span>\",\"description\":null,\"image\":\"website_images\\/e-books.webp\",\"link\":null,\"icon_svg\":null,\"icon_class\":null,\"color_class\":null,\"badge_text\":\"Read our ebooks\",\"button_text\":null,\"button_url\":null,\"btn_text\":null,\"subtitle\":\"Must-read guides, handpicked for their popularity among global exporters\",\"paragraphs\":null,\"question\":null,\"answer\":null,\"name\":null,\"avatar\":null,\"rating\":null,\"text\":null,\"value\":null,\"label\":null,\"suffix\":null,\"logo_url\":null,\"alt\":null}', 1, 'Active', '2026-05-16 13:27:29', '2026-05-22 05:53:25'),
(5, 'section_header', 'section_header_content', 'Grow your knowledge to grow your business', 'EGet your hands on our eBooks and learn about everything required to grow your business. Be it marketing, sales, logistics, or social media. Access the A to Z guides for guaranteed business growth.. Join our growing network of satisfied clients who depend on us for easy, secure, fast, and efficient logistics solutions. More than three decades (30+ years) of our positive track record speaks for itself.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"title\":\"Grow your knowledge to grow your business\",\"description\":\"EGet your hands on our eBooks and learn about everything required to grow your business. Be it marketing, sales, logistics, or social media. Access the A to Z guides for guaranteed business growth.. Join our growing network of satisfied clients who depend on us for easy, secure, fast, and efficient logistics solutions. More than three decades (30+ years) of our positive track record speaks for itself.\"}', 1, 'Active', '2026-05-16 13:27:29', '2026-05-16 13:27:29'),
(6, 'faq', 'faq_header', 'Frequently Asked Questions', NULL, NULL, NULL, NULL, NULL, 'Common Questions', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"sidebar_image\":\"https:\\/\\/i.pinimg.com\\/originals\\/f6\\/5d\\/46\\/f65d4681649d85bc91c86872a1775919.gif\",\"sidebar_title\":\"Need personalized help?\",\"sidebar_description\":\"Our logistics experts are available 24\\/7 to assist your requirements.\",\"contact_box_title\":\"Contact Us\",\"contact_box_description\":\"For urgent inquiries regarding your current shipment status.\",\"contact_button_text\":\"Message Support\"}', NULL, '{\"badge\":\"Common Questions\",\"title\":\"Frequently Asked Questions\",\"sidebar_image\":\"https:\\/\\/i.pinimg.com\\/originals\\/f6\\/5d\\/46\\/f65d4681649d85bc91c86872a1775919.gif\",\"sidebar_title\":\"Need personalized help?\",\"sidebar_description\":\"Our logistics experts are available 24\\/7 to assist your requirements.\",\"contact_box_title\":\"Contact Us\",\"contact_box_description\":\"For urgent inquiries regarding your current shipment status.\",\"contact_button_text\":\"Message Support\"}', 1, 'Active', '2026-05-16 13:27:29', '2026-05-16 14:17:23'),
(7, 'faq', 'faq_item_1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'How do I get started?', 'To connect with our team, you have to register yourself, get a quote, and schedule your first pickup. Thereafter, the team will guide you through every step of the process.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"How do I get started?\",\"answer\":\"To connect with our team, you have to register yourself, get a quote, and schedule your first pickup. Thereafter, the team will guide you through every step of the process.\"}', 2, 'Active', '2026-05-16 13:27:29', '2026-05-16 13:27:29'),
(8, 'faq', 'faq_item_2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'How does United Worldwide Couriers meet your shipping and logistics needs?', 'To provide the best freight management solutions, we work with broad strategies, technologies, and services to simplify the planning, storage, and movement of goods.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"How does United Worldwide Couriers meet your shipping and logistics needs?\",\"answer\":\"To provide the best freight management solutions, we work with broad strategies, technologies, and services to simplify the planning, storage, and movement of goods.\"}', 3, 'Active', '2026-05-16 13:27:29', '2026-05-16 13:27:29'),
(9, 'faq', 'faq_item_3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'What packaging standards should we follow for shipping?', 'We utilize study and secure packaging for small to large packages to protect your goods during transit. In case of fragile items, they will be cushioned enough and clearly labelled as \"Fragile\". In addition, we also provide a packaging and labelling guide for all new on boarders for no confusion and faster results.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"What packaging standards should we follow for shipping?\",\"answer\":\"We utilize study and secure packaging for small to large packages to protect your goods during transit. In case of fragile items, they will be cushioned enough and clearly labelled as \\\"Fragile\\\". In addition, we also provide a packaging and labelling guide for all new on boarders for no confusion and faster results.\"}', 4, 'Active', '2026-05-16 13:27:29', '2026-05-16 13:27:29'),
(10, 'faq', 'faq_item_4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'How do we calculate cost?', 'The exact shipping cost will be calculated based on your goods\' weight, dimensions, destinations, where it is expected to be delivered, and the delivery speed. If you are interested in knowing the accurate pricing, you are welcome to connect with the team.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"How do we calculate cost?\",\"answer\":\"The exact shipping cost will be calculated based on your goods\' weight, dimensions, destinations, where it is expected to be delivered, and the delivery speed. If you are interested in knowing the accurate pricing, you are welcome to connect with the team.\"}', 5, 'Active', '2026-05-16 13:27:29', '2026-05-16 13:27:29'),
(11, 'faq', 'faq_item_5', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Will I be notified about my shipment status?', 'Yes. To keep the clients informed, our team provides regular updates via email or SMS throughout the shipping process.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"Will I be notified about my shipment status?\",\"answer\":\"Yes. To keep the clients informed, our team provides regular updates via email or SMS throughout the shipping process.\"}', 6, 'Active', '2026-05-16 13:27:29', '2026-05-16 13:27:29'),
(12, 'faq', 'faq_item_6', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Does United Worldwide Couriers handle bulk or commercial shipments?', 'Yes, we specialize in managing bulk as well as commercial consignments with easy-flowing coordination, dedicated handling, secure transit, and timely delivery. This remains the same for both small and large volumes.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"Does United Worldwide Couriers handle bulk or commercial shipments?\",\"answer\":\"Yes, we specialize in managing bulk as well as commercial consignments with easy-flowing coordination, dedicated handling, secure transit, and timely delivery. This remains the same for both small and large volumes.\"}', 7, 'Active', '2026-05-16 13:27:29', '2026-05-16 13:27:29'),
(13, 'faq', 'faq_item_7', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Can I schedule a pickup for my shipment?', 'Yes, you can easily schedule a pick up at your preferred time either by reaching out to our team online (via our website) or by directly contacting our customer support.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"Can I schedule a pickup for my shipment?\",\"answer\":\"Yes, you can easily schedule a pick up at your preferred time either by reaching out to our team online (via our website) or by directly contacting our customer support.\"}', 8, 'Active', '2026-05-16 13:27:29', '2026-05-16 13:27:29'),
(14, 'faq', 'faq_item_8', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'How can I track my shipment?', 'Through our online tracking system, you can track your shipment in real-time. For that, you just have to enter the tracking ID provided on our website dashboard to get live updates.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"How can I track my shipment?\",\"answer\":\"Through our online tracking system, you can track your shipment in real-time. For that, you just have to enter the tracking ID provided on our website dashboard to get live updates.\"}', 9, 'Active', '2026-05-16 13:27:29', '2026-05-16 13:27:29'),
(15, 'faq', 'faq_item_9', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Will my package be picked up by the United Worldwide Couriers team only?', 'It depends on the service and location. So, your shipment may be picked up either by our in-house delivery team or by third-party courier partners. On the contrary, we ensure strict quality control and safe handling for whatever the case may be.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"Will my package be picked up by the United Worldwide Couriers team only?\",\"answer\":\"It depends on the service and location. So, your shipment may be picked up either by our in-house delivery team or by third-party courier partners. On the contrary, we ensure strict quality control and safe handling for whatever the case may be.\"}', 10, 'Active', '2026-05-16 13:27:29', '2026-05-16 13:27:29'),
(16, 'faq', 'faq_item_10', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Do you provide customs clearance support?', 'Yes, while others face limited support, we complete international customs documentation and clearance faster. This way, we support rapid shipping without delays.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"Do you provide customs clearance support?\",\"answer\":\"Yes, while others face limited support, we complete international customs documentation and clearance faster. This way, we support rapid shipping without delays.\"}', 11, 'Active', '2026-05-16 13:27:29', '2026-05-16 13:27:29'),
(17, 'faq', 'faq_item_11', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'What happens if my shipment is delayed or stuck?', 'First things first, the team proactively monitors the shipment to identify and resolve potential issues before they escalate. Still, if an issue occurs, the internal team coordinates with the partners to resolve the situation quickly.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"What happens if my shipment is delayed or stuck?\",\"answer\":\"First things first, the team proactively monitors the shipment to identify and resolve potential issues before they escalate. Still, if an issue occurs, the internal team coordinates with the partners to resolve the situation quickly.\"}', 12, 'Active', '2026-05-16 13:27:29', '2026-05-16 13:27:29'),
(21, 'hero', 'hero_content', 'eBooks for  <span class=\"moving-gradient-text\">Exporters</span>', NULL, 'images/e-books.webp', NULL, NULL, NULL, 'Read our ebooks', NULL, NULL, NULL, 'Must-read guides, handpicked for their popularity among global exporters', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"badge_text\":\"Read our ebooks\",\"title\":\"eBooks for  <span class=\\\"moving-gradient-text\\\">Exporters<\\/span>\",\"subtitle\":\"Must-read guides, handpicked for their popularity among global exporters\",\"image\":\"images\\/e-books.webp\"}', 1, 'Active', '2026-05-16 13:32:49', '2026-05-16 13:32:49'),
(22, 'section_header', 'section_header_content', 'Grow your knowledge to grow your business', 'EGet your hands on our eBooks and learn about everything required to grow your business. Be it marketing, sales, logistics, or social media. Access the A to Z guides for guaranteed business growth.. Join our growing network of satisfied clients who depend on us for easy, secure, fast, and efficient logistics solutions. More than three decades (30+ years) of our positive track record speaks for itself.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"title\":\"Grow your knowledge to grow your business\",\"description\":\"EGet your hands on our eBooks and learn about everything required to grow your business. Be it marketing, sales, logistics, or social media. Access the A to Z guides for guaranteed business growth.. Join our growing network of satisfied clients who depend on us for easy, secure, fast, and efficient logistics solutions. More than three decades (30+ years) of our positive track record speaks for itself.\"}', 1, 'Active', '2026-05-16 13:32:49', '2026-05-16 13:32:49'),
(38, NULL, NULL, 'The Final Experiment | The Mystery Thriller of the Year | Witness the Fall of our World', 'Yaksh is a struggling salesman trying to find his place in the bustling streets of Delhi. A chance encounter with Vijitha, the protest leader, lands him in a totally different world. What begins as an act of curiosity pulls him into a shadowy conspiracy far beyond his understanding.\r\nYudhisthir is a successful consultant to the powerful and enigmatic founder of Dyēus, the research company pushing the boundaries of human innovation. But when a robbery in Japan uproots his entire life, Yudhisthir is forced to confront the terrifying potential of Dyeus’ groundbreaking technology.\r\nCan Yaksh and Yudhisthir uncover the truth before it’s too late?\r\nOr will they become casualties of a world teetering on the edge of transformation?\r\nThe Final Experiment is a gripping mystery thriller that takes you on a mind-bending journey where nothing is as it seems.', 'website_images/1779100736_413PNLwzypL._SY445_SX342_FMwebp_.webp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ebook_pdf/1779100736_file-sample_150kB.pdf', NULL, 0, 'Active', '2026-05-18 05:08:56', '2026-05-18 06:02:21');
