INSERT INTO `home_page` (`id`, `section`, `field_name`, `content`, `sort_order`, `updated_at`) VALUES
(180, 'hero', 'badge', 'Trusted by Growing Businesses Across India', 0, '2026-05-08 03:59:08'),
(181, 'hero', 'title', 'E-commerce Speed. B2B Reliability. Ship Simply <br class=\"d-none d-md-block\"> <span class=\"moving-gradient-text\">United Couriers.</span>', 0, '2026-06-01 10:24:57'),
(182, 'hero', 'subtitle', 'From First Click to Delivery. Your Gateway to Seamless Shipping Worldwide.', 0, '2026-05-20 08:57:13'),
(183, 'about', 'badge', 'About United Worldwide Couriers', 0, '2026-05-08 09:07:23'),
(184, 'about', 'heading', 'One Partner. Infinite Logistics Possibilities.', 0, '2026-05-20 08:59:35'),
(185, 'about', 'description', 'United Worldwide Couriers delivers integrated logistics solutions for modern B2B enterprises, e-commerce brands, and growing businesses. Our services cover international Air Express & Freight, pan-India pickup, customs clearance with documentation support, and fulfilment solutions, all managed under one reliable platform. <br> With a strong operational network and an experienced logistics team, we help clients move shipments efficiently, reduce delays, and manage complex requirements with confidence. Every shipment is handled with proactive coordination, transparent tracking, and dedicated customer support to ensure a smooth and dependable delivery experience.', 0, '2026-05-08 09:07:23'),
(186, 'about', 'feature1_title', 'Tailored Shipping for Every Business Model', 1, '2026-05-08 09:07:23'),
(187, 'about', 'feature1_desc', 'Whether you are a B2B manufacturer, e-commerce brand, distributor, dropshipper, or individual shipper, we manage your complete delivery journey across 220+ countries with speed, visibility, and dependable support.', 1, '2026-05-20 09:01:27'),
(188, 'about', 'feature2_title', 'Smarter Cost for High-Volume Shipping', 2, '2026-05-08 09:07:23'),
(189, 'about', 'feature2_desc', 'Our volume-based pricing, shipment consolidation, and optimized routing solutions help businesses reduce logistics costs while improving efficiency across international operations.', 2, '2026-05-08 09:07:23'),
(190, 'about', 'feature3_title', 'Built to Scale With Your Business', 3, '2026-05-08 09:08:46'),
(191, 'about', 'feature3_desc', 'With warehousing, cross-docking, and fulfilment support, we help businesses scale from hundreds to thousands of shipments a day without compromising service quality, timelines, or customer experience.', 3, '2026-05-08 09:07:23'),
(192, 'process', 'section_tag', 'Get Started', 0, '2026-05-26 07:36:46'),
(193, 'process', 'heading', 'Start Shipping with us in 4 Simple Steps', 0, '2026-05-26 07:38:10'),
(194, 'process', 'step_title', 'Create Your Account', 1, '2026-05-26 07:40:06'),
(195, 'process', 'step_desc', 'Get started and set up your shipping profile to manage orders, bookings, invoices, and tracking from one dashboard.', 1, '2026-05-26 07:41:33'),
(196, 'process', 'step_title', 'Choose Your Service', 2, '2026-05-08 09:07:23'),
(197, 'process', 'step_desc', 'Enter your shipment details and compare available delivery options based on price, speed, and service type.', 2, '2026-05-08 09:07:23'),
(198, 'process', 'step_title', 'Schedule Your Pickup', 3, '2026-05-08 09:07:23'),
(199, 'process', 'step_desc', 'Select your preferred service, confirm the shipment, and book your pickup.', 3, '2026-05-08 09:07:23'),
(200, 'process', 'step_title', 'Track Your Shipment', 4, '2026-05-08 09:07:23'),
(201, 'process', 'step_desc', 'Stay updated from pickup to final delivery with real-time tracking and proactive shipment updates.', 4, '2026-05-08 09:07:23'),
(202, 'service_card', 'label', 'Express Air Freight Solutions', 1, '2026-05-20 09:28:14'),
(203, 'service_card', 'title', 'Air Express Services Built Around Your Needs', 1, '2026-05-20 09:28:43'),
(204, 'service_card', 'description', 'Our Express services are designed to give customers complete flexibility — from faster 3–4 day delivery options to more economical 8–10 day delivery solutions, allowing every customer to choose a service based on their urgency, budget, and delivery timeline.', 1, '2026-05-20 09:31:52'),
(205, 'service_card', 'small1_title', 'Flexible Delivery Options', 1, '2026-05-20 09:32:23'),
(206, 'service_card', 'small1_desc', 'Priority and economy services are designed around your budget and timeline.', 1, '2026-05-08 09:07:23'),
(207, 'service_card', 'small2_title', 'Real Time Tracking', 1, '2026-05-08 09:07:23'),
(208, 'service_card', 'small2_desc', 'Instant tracking updates from pickup to final door-to-door delivery.', 1, '2026-05-08 09:07:23'),
(209, 'service_card', 'label', 'E-commerce Logistics Solutions', 2, '2026-05-08 09:07:23'),
(210, 'service_card', 'title', 'Built for Sellers. Designed for scale', 2, '2026-05-08 09:07:23'),
(211, 'service_card', 'description', 'Connect your marketplace account directly with our platform and ship orders with ease — starting from lightweight parcels of just 50g to high-volume e-commerce shipments.', 2, '2026-05-08 09:07:23'),
(212, 'service_card', 'small1_title', 'No Platform Fee', 2, '2026-05-08 09:07:23'),
(213, 'service_card', 'small1_desc', 'Reduce costs and protect your margins.', 2, '2026-05-08 09:07:23'),
(214, 'service_card', 'small2_title', 'Complete Fulfilment Support', 2, '2026-05-08 09:07:23'),
(215, 'service_card', 'small2_desc', 'Order processing, pickup, dispatch, tracking, and final delivery.', 2, '2026-05-08 09:07:23'),
(216, 'service_card', 'label', 'Warehousing Solutions', 3, '2026-05-08 09:07:23'),
(217, 'service_card', 'title', 'Store. Manage. Fulfil—Smarter from The USA', 3, '2026-05-08 09:07:23'),
(218, 'service_card', 'description', 'Our US warehousing facility helps businesses reduce delivery timelines, manage inventory efficiently, and fulfil international orders with greater speed, control, and reliability.', 3, '2026-05-08 09:07:23'),
(219, 'service_card', 'small1_title', 'Inventory Management', 3, '2026-05-08 09:07:23'),
(220, 'service_card', 'small1_desc', 'Real-time stock visibility with better operational control.', 3, '2026-05-08 09:07:23'),
(221, 'service_card', 'small2_title', 'Fast Fulfillment', 3, '2026-05-08 09:07:23'),
(222, 'service_card', 'small2_desc', 'Speedy dispatch support for e-commerce and B2B shipments.', 3, '2026-05-08 09:07:23'),
(223, 'shipping_solutions', 'heading', 'Shipping Solutions Designed Around You!', 0, '2026-05-20 09:43:00'),
(224, 'shipping_solutions', 'description', 'No two businesses ship the same way. That\'s why United Worldwide Couriers offers flexible logistics solutions built around your shipment type, delivery timeline, budget, and business goals. Whether you need B2B Export Support, Dropshipping Solutions, Marketplace shipping, or personal deliveries for friends and family, we help you choose the right service with clarity, reliability, and complete support.', 0, '2026-05-20 09:43:35'),
(225, 'shipping_solutions', 'card_title', 'B2B Shipping Made Simple', 1, '2026-05-26 07:42:49'),
(226, 'shipping_solutions', 'card_desc', 'Move commercial shipments with confidence. We support exporters, manufacturers, distributors, and growing businesses with secure handling, flexible delivery options, documentation support, and competitive pricing for bulk volumes.', 1, '2026-05-20 09:51:55'),
(227, 'shipping_solutions', 'card_point1', 'Fragile Goods: <span style=\"font-weight: 400;\">Secure handling for sensitive and high-volume shipments<span>', 1, '2026-05-26 11:45:11'),
(228, 'shipping_solutions', 'card_point2', 'Bulk Shipments: <span style=\"font-weight: 400;\">Cost-effective solutions and customs clearance support.<span>', 1, '2026-05-26 11:46:55'),
(229, 'shipping_solutions', 'card_cta', 'Start Shipping', 1, '2026-05-08 09:07:23'),
(230, 'shipping_solutions', 'card_title', 'Marketplace Shipping', 3, '2026-05-19 12:31:21'),
(231, 'shipping_solutions', 'card_desc', 'Connect your online store with our shipping platform and manage orders from leading marketplaces like Amazon, eBay, Etsy, Walmart, and more, with faster processing, real-time tracking, and reliable delivery support.', 3, '2026-05-26 23:47:03'),
(232, 'shipping_solutions', 'card_point1', 'End-to-End Support: <span style=\"font-weight:400\">Manage multiple tasks with one easy-to-use dashboard.</span>', 2, '2026-05-26 11:57:09'),
(233, 'shipping_solutions', 'card_point2', 'Automated Order flow: <span style=\"font-weight:400\">Manage. Process. Dispatch.</span>', 2, '2026-05-26 11:57:59'),
(234, 'shipping_solutions', 'card_cta', 'Start Shipping', 2, '2026-05-08 09:07:23'),
(235, 'shipping_solutions', 'card_title', 'Dropshipping Solutions', 2, '2026-05-19 12:31:42'),
(236, 'shipping_solutions', 'card_desc', 'Dropshipping Solutions Launch and Scale your Online business with reliable door-to-door Shipping. Whether you sell through Shopify, your own website, or a dropshiping store, we help you ship products directly to customers with speed, tracking and complete reliability.', 2, '2026-05-26 23:51:36'),
(237, 'shipping_solutions', 'card_point1', 'Real-Time Tracking: <span style=\"font-weight:400\">Complete visibility for every shipment.<span>', 3, '2026-05-26 11:56:08'),
(238, 'shipping_solutions', 'card_point2', 'Seller-Friendly Shipping:  <span style=\"font-weight:400\">Built for marketplace sellers handling small packages daily and high volume.</span>', 3, '2026-05-26 11:53:20'),
(239, 'shipping_solutions', 'card_cta', 'Start Shipping', 3, '2026-05-08 09:07:23'),
(240, 'shipping_solutions', 'card_title', 'Overseas Friends & Family', 4, '2026-05-08 09:07:23'),
(241, 'shipping_solutions', 'card_desc', 'Send personal packages to your loved ones worldwide with safe handling, timely delivery, and clear updates at every step.', 4, '2026-05-08 09:07:23'),
(242, 'shipping_solutions', 'card_point1', 'International Delivery: <span style=\"font-weight:400\">Reliable shipping for gifts, documents, clothes, and personal items.</span>', 4, '2026-05-26 11:50:13'),
(243, 'shipping_solutions', 'card_point2', 'Live Updates: <span style=\"font-weight:400\">Stay informed from pickup to delivery.</span>', 4, '2026-05-26 11:50:34'),
(244, 'shipping_solutions', 'card_cta', 'Start Shipping', 4, '2026-05-26 07:55:43'),
(265, 'faq', 'question', 'How to book my shipment?', 1, '2026-05-26 12:28:19'),
(266, 'faq', 'answer', 'Follow our simple 4-step process to book your first package. Our team will call you to guide you through each step.', 1, '2026-05-26 12:30:34'),
(267, 'faq', 'question', 'What kind of products can we ship worldwide?', 2, '2026-05-26 12:31:27'),
(268, 'faq', 'answer', 'From fashion, artificial jewellery, handicrafts, and home décor to electronics, nutraceuticals, and auto parts — most of them are eligible for clearance. Some countries may have restrictions on specific items.', 2, '2026-05-26 12:31:51'),
(269, 'faq', 'question', 'Do united couriers offer same day pickup?', 3, '2026-05-26 12:32:56'),
(270, 'faq', 'answer', 'Yes, we do offer same day pickup, provided the order is placed before 12pm', 3, '2026-05-26 12:33:15'),
(271, 'faq', 'question', 'How can I track my shipment?', 4, '2026-05-26 12:43:36'),
(272, 'faq', 'answer', 'follow these simple steps to track your shipment 1)Click on our Tracking button on top corner. 2)Enter your Tracking Number (AWB Number)\n3)Receive real-time end-to-end tracking', 4, '2026-05-26 12:41:28'),
