INSERT INTO `privacy_policy_page` (`id`, `section_key`, `title`, `paragraphs`, `list_items_text`, `sort_order`, `effective_date`, `footer_heading`, `footer_email`, `created_at`, `updated_at`) VALUES
(1, '_page_meta', 'Our Privacy Policy', '<p style=\"text-align:center\"><strong>If you have any questions regarding this Privacy Policy or our treatment of your personal data, please get in touch with us at</strong></p>', 'Processing and tracking international shipments.\nCommunicating real-time delivery status updates.\nEnhancing our website user experience.\nComplying with global customs and regulatory requirements.', 0, 'October 2025', 'Have Questions?', 'info@unitedcouriers.biz', '2026-05-13 02:05:18', '2026-06-01 23:15:35'),
(2, 'data_collection', 'What Information Do We Collect?', '<p><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\">United Worldwide Couriers may collect, store, and process the following kinds of data covering both personal and office information:</span></span></span></p>\r\n\r\n<ul>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\">(a) Full name, contact details, and address information provided during registration, account creation, or shipment booking.</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\">(b) Information about your visits to and use of this website.</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\">(c) Information about any interactions carried out between you and us in relation to this website.</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\">(d) Information that you provide for registration, subscriptions, or email notifications.</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\">(e) Information you provide for booking shipments and creation of regulatory transportation documents.</span></span></span></li>\r\n	<li style=\"list-style-type:disc\"><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\">(f) Payment-related information submitted during the booking or transaction process.</span></span></span></li>\r\n</ul>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\">We may also collect, store, and use non-personal data about your visits to and use of this website.</span></span></span></p>', '', 1, NULL, NULL, NULL, '2026-05-13 02:05:18', '2026-05-21 04:21:03'),
(3, 'data_usage', 'Information About Website Visits', '<p><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\">Whenever a user visits our site, we may collect information about their computer and their visits, such as IP address, geographical location, browser type, referral source, pages visited, and duration of visit.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\">In addition, we also collect information related to your device, the operating systems you are accessing our site with, clickstream data, and navigation patterns across the website. This helps us improve usability and analyze website traffic</span></span></span></p>', '', 2, NULL, NULL, NULL, '2026-05-13 02:05:18', '2026-05-21 04:25:58'),
(4, 'data_sharing', 'Using Your Personal Data', '<p><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\">Personal information collected through this website is used strictly for the purposes specified in this privacy policy or relevant parts of the website, including:</span></span></span></p>\n\n<ul>\n	<li style=\"list-style-type:disc\"><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\"><strong>Service Delivery:</strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\"> With the data collected, we process shipment bookings, generate regulatory transportation documents, and ensure the delivery of services requested by the user.</span></span></span></li>\n	<li style=\"list-style-type:disc\"><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\"><strong>Account Management:</strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\"> Manage user registrations, preferences, and account-related communications.</span></span></span></li>\n	<li style=\"list-style-type:disc\"><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\"><strong>Website Personalization:</strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\"> With behavioural data and preferences, we personalize the user experience and improve the browsing experience.</span></span></span></li>\n	<li style=\"list-style-type:disc\"><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\"><strong>Service Communications:</strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\"> To our loyal customer base, we send discount offers, send users relevant, non-marketing information related to their bookings, account activity, or service updates.&nbsp;</span></span></span></li>\n	<li style=\"list-style-type:disc\"><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\"><strong>Marketing Communications:</strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\"> We use your data to send promotional information relating to United&#39;s services. Keep in mind that this information will be shared with those who have consented to receive such communications.</span></span></span></li>\n	<li style=\"list-style-type:disc\"><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\"><strong>Analytics and Improvement:</strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\"> To analyze website traffic, monitor performance, improve the functionality, and usability of our website.&nbsp;</span></span></span></li>\n	<li style=\"list-style-type:disc\"><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\"><strong>Legal Compliance:</strong></span></span></span><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\"> Last but not least, we use the data collected from our users to comply with legal obligations, in connection with legal proceedings, regulatory requirements, and lawful requests from authorities. Overall, we use data to establish, exercise, or defend legal rights (including fraud prevention or credit risk reduction).</span></span></span></li>\n</ul>\n\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\">Therefore, United Worldwide Couriers do not use your personal information for any purpose beyond those outlined above without prior notification and, where required, your explicit consent</span></span></span></p>', '', 3, NULL, NULL, NULL, '2026-05-13 02:05:18', '2026-05-21 04:24:22'),
(5, 'data_security', 'Security of Your Personal Data', '<p><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\">United Worldwide Couriers takes reasonable and appropriate technical and organisational measures to protect your personal information against unauthorised access, loss, misuse, alteration of your personal or business data, and destruction.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\">For your knowledge, all personal data we collect from our users is stored on secure servers with access controls in place. However, the transmission of data over the internet is inherently not completely secure, and United cannot guarantee the absolute security of information sent to or from this website.</span></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\">However, we shall not be held liable for damages that may arise from the misuse of user information that occurs beyond the Company&#39;s reasonable control</span></span></span></p>', '', 4, NULL, NULL, NULL, '2026-05-13 02:05:18', '2026-05-21 04:27:22'),
(6, 'cookies_policy', 'Third-Party Websites', '<p><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\">Our website may contain links to various external third-party websites for the convenience of users. Thereby, United Worldwide Couriers is not responsible for the privacy policies, practices, or content of any third-party websites. We always encourage users to review the privacy policies of any external websites they visit independently, prior to seeking their service or information.</span></span></span></p>', '', 5, NULL, NULL, NULL, '2026-05-13 02:05:18', '2026-05-21 04:27:50'),
(7, 'user_rights', 'Cookie Policy', '<p><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\">United Worldwide Couriers uses cookies to improve browsing experience and collect anonymous usage data. Cookies are small data files stored on your computer. In addition, we use cookies to personalize user experience, analytics, and advertising. If you are not interested in sharing such data, you can choose to disable cookies via your browser settings at any time. But keep in mind that doing so may impact certain features of our website</span></span></span></p>', '', 6, NULL, NULL, NULL, '2026-05-13 02:05:18', '2026-05-21 04:28:10'),
(8, 'policy_updates', 'Changes to This Privacy Policy', '<p><span style=\"font-size:11pt\"><span style=\"font-family:Lexend,sans-serif\"><span style=\"color:#000000\">United Worldwide Couriers reserves the right to update or amend this Privacy Policy at any time, without prior notice. Any changes will be published on this page with an updated effective date. Therefore, your continued use of the website following the publication of any changes constitutes your acceptance of the revised policy. So, review this Privacy Policy periodically to stay informed of any updates.</span></span></span></p>', '', 7, NULL, NULL, NULL, '2026-05-13 02:05:18', '2026-05-21 04:28:26');
INSERT INTO `refund_and_cancellation_policy_page` (`id`, `section_key`, `title`, `paragraphs`, `list_items_text`, `sort_order`, `effective_date`, `footer_heading`, `footer_email`, `created_at`, `updated_at`) VALUES
(1, '_page_meta', 'Refund & Cancellation Policy Meta', 'Your privacy is our priority. This policy outlines how United Worldwide Couriers collects, uses, and protects your information.', NULL, 0, 'October 2025', 'Need Assistance?', 'contact@unitedcourier.com', '2026-05-13 03:56:59', '2026-05-13 04:25:59'),
(2, 'cancellation_policy', 'Cancellation Policy', 'At United Worldwide Couriers, we understand that plans change. Our cancellation rules are as follows:', 'Pre-Pickup: Shipments can be cancelled at no charge before the courier has been dispatched for pickup.\nPost-Pickup: Once a shipment is picked up, it cannot be cancelled. However, you may request a \"Return to Sender\" service, which will incur standard return shipping fees.\nLabel Generation: If a shipping label was generated but not used, a cancellation request must be filed within 24 hours to avoid processing fees.', 1, NULL, NULL, NULL, '2026-05-13 03:56:59', '2026-05-13 04:27:00'),
(3, 'refund_eligibility', 'Refund Eligibility', 'Refunds are evaluated on a case-by-case basis. You may be eligible for a refund if:', 'The service was not provided due to an error on our part.\nThe shipment was lost within our network (verified after investigation).\nA duplicate payment was accidentally made for the same tracking number.\nA guaranteed delivery service failed to meet the specified timeline (excluding customs delays).', 2, NULL, NULL, NULL, '2026-05-13 03:56:59', '2026-05-13 03:56:59'),
(4, 'refund_process', 'Refund Process', 'To request a refund, please follow these steps:', 'Submit a formal request via our support portal or email within 7 business days of the incident.\nProvide the Tracking Number and Proof of Payment.\nOnce approved, refunds are processed within 7-10 business days to the original payment method.', 3, NULL, NULL, NULL, '2026-05-13 03:56:59', '2026-05-13 03:56:59'),
(5, 'non_refundable_items', 'Non-Refundable Items', 'Certain fees and charges are strictly non-refundable:', 'Customs duties, taxes, and government regulatory fees.\nInsurance premiums once the shipment has departed the origin.\nHandling fees for prohibited or restricted items.\nSurcharges related to incorrect address provided by the sender.', 4, NULL, NULL, NULL, '2026-05-13 03:56:59', '2026-05-13 03:56:59'),
(6, 'service_delays', 'Service Delays', 'Refunds are not provided for delays caused by circumstances beyond our control (Force Majeure), including but not limited to:', 'Severe weather conditions or natural disasters.\nCustoms clearance procedures or inspections.\nGlobal supply chain disruptions or strikes.\nIncorrect or incomplete documentation provided by the customer.', 5, NULL, NULL, NULL, '2026-05-13 03:56:59', '2026-05-13 03:56:59');
