(2, 2, 'fb.com/sharon.roy', 'sharon.roy', 'linkedin.com/in/sharonroy', '@sharonroy', '+11234567890', '@sharon_roy', '2026-05-09 04:29:41'),
(3, 3, NULL, 'darlee.skype', 'linkedin.com/in/darlee', NULL, '+15432198765', '@darlee_r', '2026-05-09 04:29:41'),
(4, 4, 'fb.com/vaughan.lewis', 'vaughan.lewis', NULL, '@vaughanL', '+16123456789', '@vaughan_lewis', '2026-05-09 04:29:41'),
(5, 5, NULL, NULL, 'linkedin.com/in/jessica', '@jesslouise', '+19112233445', '@jessica_louise', '2026-05-09 04:29:41');
INSERT INTO `subscribers` (`id`, `email`, `created_at`, `updated_at`) VALUES
