(1, 'hero', 'hero_content', 'Track Your <span class=\"moving-gradient-text\">Orders Easily</span>', NULL, 'website_images/tracking.webp', NULL, NULL, NULL, 'Free Tool · Instant Results', 'Track Now', NULL, NULL, 'Just enter your Mobile Number, AWB tracking number or Order ID & it\'s done.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"title\":\"Track Yours <span class=\\\"moving-gradient-text\\\">Orders Easily<\\/span>\",\"description\":null,\"image\":\"website_images\\/tracking.webp\",\"link\":null,\"icon_svg\":null,\"icon_class\":null,\"color_class\":null,\"badge_text\":\"Free Tool \\u00b7 Instant Results\",\"button_text\":\"Track Now\",\"button_url\":null,\"btn_text\":null,\"subtitle\":\"Just enter your Mobile Number, AWB tracking number or Order ID & it\'s done.\",\"paragraphs\":null,\"question\":null,\"answer\":null,\"name\":null,\"avatar\":null,\"rating\":null,\"text\":null,\"value\":null,\"label\":null,\"suffix\":null,\"logo_url\":null,\"alt\":null}', 1, 'Active', '2026-05-16 14:44:36', '2026-06-03 03:16:27'),
(2, 'track_form', 'track_form_content', 'AWB Number', NULL, NULL, NULL, NULL, NULL, NULL, 'Track Now', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"field_1_label\":\"AWB Number\",\"field_1_placeholder\":\"Airway Bill Number\",\"field_2_label\":\"Order Id\",\"field_2_placeholder\":\"eg: 983434599\",\"field_3_label\":\"Phone Number\",\"field_3_placeholder\":\"+91 9876543210\"}', NULL, '{\"title\":\"Tracks <span class=\\\"gradient-text\\\">Now<\\/span>\",\"description\":null,\"image\":null,\"link\":null,\"icon_svg\":null,\"icon_class\":null,\"color_class\":null,\"badge_text\":null,\"button_text\":\"Track Now\",\"button_url\":null,\"btn_text\":null,\"subtitle\":null,\"paragraphs\":null,\"question\":null,\"answer\":null,\"name\":null,\"avatar\":null,\"rating\":null,\"text\":null,\"value\":null,\"label\":null,\"suffix\":null,\"logo_url\":null,\"alt\":null,\"field_1_label\":\"AWB Number\",\"field_1_placeholder\":\"Airway Bill Number\",\"field_2_label\":\"Order Id\",\"field_2_placeholder\":\"eg: 983434599\",\"field_3_label\":\"Phone Number\",\"field_3_placeholder\":\"+91 9876543210\"}', 2, 'Active', '2026-05-16 14:44:36', '2026-06-03 03:21:00'),
(3, 'features', 'features_header', 'What\'s your order status?', 'Carriers use dimensional weight to price large, light packages — here\'s what you need to know.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"title\":\"What\'s your order statuss?\",\"description\":\"Carriers use dimensional weight to price large, light packages \\u2014 here\'s what you need to know.\",\"image\":null,\"link\":null,\"icon_svg\":null,\"icon_class\":null,\"color_class\":null,\"badge_text\":null,\"button_text\":null,\"button_url\":null,\"btn_text\":null,\"subtitle\":null,\"paragraphs\":null,\"question\":null,\"answer\":null,\"name\":null,\"avatar\":null,\"rating\":null,\"text\":null,\"value\":null,\"label\":null,\"suffix\":null,\"logo_url\":null,\"alt\":null}', 1, 'Active', '2026-05-16 14:44:36', '2026-06-03 03:19:17'),
(4, 'features', 'feature_1', 'Order Placed', 'Your order has been successfully placed and is being processed by the seller.', NULL, 'fa-solid fa-check-to-slot', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"icon_color\":\"blue\",\"icon_color_code\":\"#2563eb\"}', NULL, '{\"icon_color\":\"blue\",\"icon\":\"fa-solid fa-check-to-slot\",\"icon_color_code\":\"#2563eb\",\"title\":\"Order Placed\",\"description\":\"Your order has been successfully placed and is being processed by the seller.\"}', 2, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36'),
(5, 'features', 'feature_2', 'Order Confirmed', 'Seller has confirmed your order and it\'s being prepared for shipment.', NULL, 'fa-solid fa-box-open', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"icon_color\":\"orange\",\"icon_color_code\":\"#f59e0b\"}', NULL, '{\"icon_color\":\"orange\",\"icon\":\"fa-solid fa-box-open\",\"icon_color_code\":\"#f59e0b\",\"title\":\"Order Confirmed\",\"description\":\"Seller has confirmed your order and it\'s being prepared for shipment.\"}', 3, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36'),
(6, 'features', 'feature_3', 'In Transit', 'Your package is on its way and moving through the delivery network.', NULL, 'fa-solid fa-truck', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"icon_color\":\"green\",\"icon_color_code\":\"#10b981\"}', NULL, '{\"icon_color\":\"green\",\"icon\":\"fa-solid fa-truck\",\"icon_color_code\":\"#10b981\",\"title\":\"In Transit\",\"description\":\"Your package is on its way and moving through the delivery network.\"}', 4, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36'),
(7, 'features', 'feature_4', 'Delivered', 'Your package has been delivered successfully. Thank you for your patience!', NULL, 'fa-solid fa-circle-check', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"icon_color\":\"purple\",\"icon_color_code\":\"#8b5cf6\"}', NULL, '{\"icon_color\":\"purple\",\"icon\":\"fa-solid fa-circle-check\",\"icon_color_code\":\"#8b5cf6\",\"title\":\"Delivered\",\"description\":\"Your package has been delivered successfully. Thank you for your patience!\"}', 5, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36'),
(8, 'about', 'about_content', 'Optimize your order <span class=\"gradient-text\">tracking experience</span>', 'Always stay informed about your shipments, regardless of your courier partner', NULL, NULL, NULL, NULL, NULL, 'Need help?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"button_link\":\"contact-us.php\",\"video_url\":\"https:\\/\\/www.youtube.com\\/embed\\/tOvpjmnh5h4?si=-O5MSnO7OXm2Wspk\",\"checklist\":[\"Real-time tracking updates across all major carriers\",\"End-to-end visibility from pickup to delivery\"]}', 'contact-us.php', '{\"title\":\"Optimize your order <span class=\\\"gradient-text\\\">tracking experience<\\/span>\",\"description\":\"Always stay informed about your shipments, regardless of your courier partner\",\"button_text\":\"Need help?\",\"button_link\":\"contact-us.php\",\"video_url\":\"https:\\/\\/www.youtube.com\\/embed\\/tOvpjmnh5h4?si=-O5MSnO7OXm2Wspk\",\"checklist\":[\"Real-time tracking updates across all major carriers\",\"End-to-end visibility from pickup to delivery\"]}', 1, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36'),
(9, 'cta', 'cta_content', 'Need any help related order??', 'Get live updates across all major carriers — end-to-end visibility from pickup to delivery for every order you export worldwide.', NULL, NULL, NULL, NULL, 'Get in Touch', 'Contact Us Now →', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"button_link\":\"#\"}', '#', '{\"badge_text\":\"Get in Touch\",\"title\":\"Need any help related order??\",\"description\":\"Get live updates across all major carriers \\u2014 end-to-end visibility from pickup to delivery for every order you export worldwide.\",\"button_text\":\"Contact Us Now \\u2192\",\"button_link\":\"#\"}', 1, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36'),
(10, 'faq', 'faq_header', 'Frequently Asked Questions', NULL, 'https://i.pinimg.com/originals/f6/5d/46/f65d4681649d85bc91c86872a1775919.gif', NULL, NULL, NULL, 'Common Questions', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"sidebar_title\":\"Need personalized help?\",\"sidebar_description\":\"Our logistics experts are available 24\\/7 to assist your requirements.\",\"contact_title\":\"Contact Us\",\"contact_description\":\"For urgent inquiries regarding your current shipment status.\",\"contact_button\":\"Message Support\"}', NULL, '{\"badge_text\":\"Common Questions\",\"title\":\"Frequently Asked Questions\",\"sidebar_title\":\"Need personalized help?\",\"sidebar_description\":\"Our logistics experts are available 24\\/7 to assist your requirements.\",\"contact_title\":\"Contact Us\",\"contact_description\":\"For urgent inquiries regarding your current shipment status.\",\"contact_button\":\"Message Support\"}', 1, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36'),
(11, 'faq', 'faq_item_1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'How do I get started?', 'To connect with our team, you have to register yourself, get a quote, and schedule your first pickup. Thereafter, the team will guide you through every step of the process.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"How do I get started?\",\"answer\":\"To connect with our team, you have to register yourself, get a quote, and schedule your first pickup. Thereafter, the team will guide you through every step of the process.\"}', 2, 'Active', '2026-05-16 14:44:36', '2026-05-16 15:06:55'),
(12, 'faq', 'faq_item_2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'How does United Worldwide Couriers meet your shipping and logistics needs?', 'To provide the best freight management solutions, we work with broad strategies, technologies, and services to simplify the planning, storage, and movement of goods.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"How does United Worldwide Couriers meet your shipping and logistics needs?\",\"answer\":\"To provide the best freight management solutions, we work with broad strategies, technologies, and services to simplify the planning, storage, and movement of goods.\"}', 3, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36'),
(13, 'faq', 'faq_item_3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'What packaging standards should we follow for shipping?', 'We utilize study and secure packaging for small to large packages to protect your goods during transit. In case of fragile items, they will be cushioned enough and clearly labelled as \"Fragile\". In addition, we also provide a packaging and labelling guide for all new on boarders for no confusion and faster results.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"What packaging standards should we follow for shipping?\",\"answer\":\"We utilize study and secure packaging for small to large packages to protect your goods during transit. In case of fragile items, they will be cushioned enough and clearly labelled as \\\"Fragile\\\". In addition, we also provide a packaging and labelling guide for all new on boarders for no confusion and faster results.\"}', 4, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36'),
(14, 'faq', 'faq_item_4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'How do we calculate cost?', 'The exact shipping cost will be calculated based on your goods\' weight, dimensions, destinations, where it is expected to be delivered, and the delivery speed. If you are interested in knowing the accurate pricing, you are welcome to connect with the team.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"How do we calculate cost?\",\"answer\":\"The exact shipping cost will be calculated based on your goods\' weight, dimensions, destinations, where it is expected to be delivered, and the delivery speed. If you are interested in knowing the accurate pricing, you are welcome to connect with the team.\"}', 5, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36'),
(15, 'faq', 'faq_item_5', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Will I be notified about my shipment status?', 'Yes. To keep the clients informed, our team provides regular updates via email or SMS throughout the shipping process.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"Will I be notified about my shipment status?\",\"answer\":\"Yes. To keep the clients informed, our team provides regular updates via email or SMS throughout the shipping process.\"}', 6, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36'),
(16, 'faq', 'faq_item_6', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Does United Worldwide Couriers handle bulk or commercial shipments?', 'Yes, we specialize in managing bulk as well as commercial consignments with easy-flowing coordination, dedicated handling, secure transit, and timely delivery. This remains the same for both small and large volumes.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"Does United Worldwide Couriers handle bulk or commercial shipments?\",\"answer\":\"Yes, we specialize in managing bulk as well as commercial consignments with easy-flowing coordination, dedicated handling, secure transit, and timely delivery. This remains the same for both small and large volumes.\"}', 7, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36'),
(17, 'faq', 'faq_item_7', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Can I schedule a pickup for my shipment?', 'Yes, you can easily schedule a pick up at your preferred time either by reaching out to our team online (via our website) or by directly contacting our customer support.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"Can I schedule a pickup for my shipment?\",\"answer\":\"Yes, you can easily schedule a pick up at your preferred time either by reaching out to our team online (via our website) or by directly contacting our customer support.\"}', 8, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36'),
(18, 'faq', 'faq_item_8', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'How can I track my shipment?', 'Through our online tracking system, you can track your shipment in real-time. For that, you just have to enter the tracking ID provided on our website dashboard to get live updates.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"How can I track my shipment?\",\"answer\":\"Through our online tracking system, you can track your shipment in real-time. For that, you just have to enter the tracking ID provided on our website dashboard to get live updates.\"}', 9, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36'),
(19, 'faq', 'faq_item_9', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Will my package be picked up by the United Worldwide Couriers team only?', 'It depends on the service and location. So, your shipment may be picked up either by our in-house delivery team or by third-party courier partners. On the contrary, we ensure strict quality control and safe handling for whatever the case may be.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"Will my package be picked up by the United Worldwide Couriers team only?\",\"answer\":\"It depends on the service and location. So, your shipment may be picked up either by our in-house delivery team or by third-party courier partners. On the contrary, we ensure strict quality control and safe handling for whatever the case may be.\"}', 10, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36'),
(20, 'faq', 'faq_item_10', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Do you provide customs clearance support?', 'Yes, while others face limited support, we complete international customs documentation and clearance faster. This way, we support rapid shipping without delays.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"Do you provide customs clearance support?\",\"answer\":\"Yes, while others face limited support, we complete international customs documentation and clearance faster. This way, we support rapid shipping without delays.\"}', 11, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36'),
(21, 'faq', 'faq_item_11', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'What happens if my shipment is delayed or stuck?', 'First things first, the team proactively monitors the shipment to identify and resolve potential issues before they escalate. Still, if an issue occurs, the internal team coordinates with the partners to resolve the situation quickly.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"What happens if my shipment is delayed or stuck?\",\"answer\":\"First things first, the team proactively monitors the shipment to identify and resolve potential issues before they escalate. Still, if an issue occurs, the internal team coordinates with the partners to resolve the situation quickly.\"}', 12, 'Active', '2026-05-16 14:44:36', '2026-05-16 14:44:36');
INSERT INTO `volumetric_calculator_page` (`id`, `page`, `section`, `data_title`, `data_description`, `data_icon`, `data_image`, `data_link`, `data_button_text`, `data_extra`, `data`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'volumetric-calculator', 'hero', 'Volumetric <span class=\"moving-gradient-text\">Weight Calculator</span>', 'Instantly calculate dimensional weight and understand how carriers charge for package size, not just weight.s', NULL, NULL, NULL, 'Calculate Now', '{\"badge_text\":\"Free Tool \\u00b7 Instant Results\",\"button_url\":\"#\"}', '{\"badge_text\":\"Free Tool \\u00b7 Instant Results\",\"title\":\"Volumetric <span class=\\\"moving-gradient-text\\\">Weight Calculator<\\/span>\",\"description\":\"Instantly calculate dimensional weight and understand how carriers charge for package size, not just weight.s\",\"button_text\":\"Calculate Now\",\"button_url\":\"#\"}', 1, 1, '2026-05-11 23:34:05', '2026-05-31 06:52:47'),
(2, 'volumetric-calculator', 'features_header', 'Understanding volumetric weight', 'Your package dimensions determine the shipping cost. Here\'s exactly how carriers calculate what you\'ll actually pay.', NULL, NULL, NULL, NULL, NULL, '{\"title\":\"Understanding volumetric weight\",\"description\":\"Your package dimensions determine the shipping cost. Here\'s exactly how carriers calculate what you\'ll actually pay.\"}', 2, 1, '2026-05-11 23:34:05', '2026-05-31 06:51:17'),
(3, 'volumetric-calculator', 'features', 'Measure all three dimensions', 'Measure the length, width, and height of the package in centimetres using tape. Always measure the outer dimensions, including packaging material, to ensure accurate calculations.', 'fa-solid fa-ruler', NULL, NULL, NULL, '{\"icon_class\":\"fa-solid fa-ruler\"}', '{\"icon_class\":\"fa-solid fa-ruler\",\"title\":\"Measure all three dimensions\",\"description\":\"Measure the length, width, and height of the package in centimetres using tape. Always measure the outer dimensions, including packaging material, to ensure accurate calculations.\"}', 3, 1, '2026-05-11 23:34:05', '2026-05-30 10:15:08'),
(4, 'volumetric-calculator', 'features', 'Apply the divisor formula', 'Multiply length × width × height to get the cubic volume, then divide by the carrier\'s divisor to get the package\'s volumetric weight.', 'fa-solid fa-divide', NULL, NULL, NULL, '{\"icon_class\":\"fa-solid fa-divide\"}', '{\"icon_class\":\"fa-solid fa-divide\",\"title\":\"Apply the divisor formula\",\"description\":\"Multiply length \\u00d7 width \\u00d7 height to get the cubic volume, then divide by the carrier\'s divisor to get the package\'s volumetric weight.\"}', 4, 1, '2026-05-11 23:34:05', '2026-05-30 10:15:35'),
(5, 'volumetric-calculator', 'features', 'Compare with actual weight', 'While many charge whichever is higher, actual or volumetric weight. Know both to optimize packaging, reduce dimensions, and lower shipping costs on every shipment.', 'fa-solid fa-scale-balanced', NULL, NULL, NULL, '{\"icon_class\":\"fa-solid fa-scale-balanced\"}', '{\"icon_class\":\"fa-solid fa-scale-balanced\",\"title\":\"Compare with actual weight\",\"description\":\"While many charge whichever is higher, actual or volumetric weight. Know both to optimize packaging, reduce dimensions, and lower shipping costs on every shipment.\"}', 5, 1, '2026-05-11 23:34:05', '2026-05-30 10:16:08'),
(6, 'volumetric-calculator', 'track_cta', 'Track any shipment in real-times', 'Get live updates across all major carriers — end-to-end visibility from pickup to delivery for every order you export worldwide.', NULL, NULL, NULL, 'Track Shipment →', '{\"live_badge\":\"\\u25cf LIVE TRACKING\",\"button_url\":null}', '{\"live_badge\":\"\\u25cf LIVE TRACKING\",\"title\":\"Track any shipment in real-times\",\"description\":\"Get live updates across all major carriers \\u2014 end-to-end visibility from pickup to delivery for every order you export worldwide.\",\"button_text\":\"Track Shipment \\u2192\",\"button_url\":null}', 6, 1, '2026-05-11 23:34:05', '2026-05-12 13:17:50'),
