(28, 'volumetric-calculator', 'faq', NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"Can I schedule a pickup for my shipment?\",\"answer\":\"Yes, you can easily schedule a pick up at your preferred time either by reaching out to our team online (via our website) or by directly contacting our customer support.\"}', '{\"question\":\"Can I schedule a pickup for my shipment?\",\"answer\":\"Yes, you can easily schedule a pick up at your preferred time either by reaching out to our team online (via our website) or by directly contacting our customer support.\"}', 7, 1, NULL, NULL),
(29, 'volumetric-calculator', 'faq', NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"How can I track my shipment?\",\"answer\":\"Through our online tracking system, you can track your shipment in real-time. For that, you just have to enter the tracking ID provided on our website dashboard to get live updates.\"}', '{\"question\":\"How can I track my shipment?\",\"answer\":\"Through our online tracking system, you can track your shipment in real-time. For that, you just have to enter the tracking ID provided on our website dashboard to get live updates.\"}', 8, 1, NULL, NULL),
(30, 'volumetric-calculator', 'faq', NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"Will my package be picked up by the United Worldwide Couriers team only?\",\"answer\":\"It depends on the service and location. So, your shipment may be picked up either by our in-house delivery team or by third-party courier partners. On the contrary, we ensure strict quality control and safe handling for whatever the case may be.\"}', '{\"question\":\"Will my package be picked up by the United Worldwide Couriers team only?\",\"answer\":\"It depends on the service and location. So, your shipment may be picked up either by our in-house delivery team or by third-party courier partners. On the contrary, we ensure strict quality control and safe handling for whatever the case may be.\"}', 9, 1, NULL, NULL),
(31, 'volumetric-calculator', 'faq', NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"Do you provide customs clearance support?\",\"answer\":\"Yes, while others face limited support, we complete international customs documentation and clearance faster. This way, we support rapid shipping without delays.\"}', '{\"question\":\"Do you provide customs clearance support?\",\"answer\":\"Yes, while others face limited support, we complete international customs documentation and clearance faster. This way, we support rapid shipping without delays.\"}', 10, 1, NULL, NULL),
(32, 'volumetric-calculator', 'faq', NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"What happens if my shipment is delayed or stuck?\",\"answer\":\"First things first, the team proactively monitors the shipment to identify and resolve potential issues before they escalate. Still, if an issue occurs, the internal team coordinates with the partners to resolve the situation quickly.\"}', '{\"question\":\"What happens if my shipment is delayed or stuck?\",\"answer\":\"First things first, the team proactively monitors the shipment to identify and resolve potential issues before they escalate. Still, if an issue occurs, the internal team coordinates with the partners to resolve the situation quickly.\"}', 11, 1, NULL, NULL),
(33, 'volumetric-calculator', 'hero', 'Weight Calculator', 'Enter your package dimensions to instantly calculate dimensional weight and understand how carriers determine your chargeable weight.', NULL, NULL, NULL, 'Calculate Now', '{\"badge_text\":\"Free Tool \\u00b7 Instant Results\",\"button_url\":\"#calculator\"}', NULL, 1, 1, '2026-05-20 05:25:31', '2026-05-20 05:25:31'),
