(38, 'volumetric-calculator', 'track_cta', 'Track any shipment in real-time', 'Get live updates across all major carriers — end-to-end visibility from pickup to delivery for every order you export worldwide.', NULL, NULL, NULL, 'Track Shipment →', '{\"live_badge\":\"\\u25cf LIVE TRACKING\"}', NULL, 6, 1, '2026-05-20 05:25:31', '2026-05-20 05:25:31'),
(39, 'volumetric-calculator', 'testimonials_header', 'Trusted by the Brands You Trust', 'Join our growing network of satisfied clients who depend on us for easy, secure, fast, and efficient logistics solutions. More than three decades (30+ years) of our positive track record speaks for itself. From on-time delivery and zero-compromise on quality to customer satisfaction, United Worldwide Couriers is completely reliable and trustworthy.', NULL, NULL, NULL, NULL, '{\"badge_url\":\"#\",\"badge_image\":\"public\\/website_images\\/google-review.png\",\"badge_alt\":\"Google\"}', NULL, 7, 1, '2026-05-20 05:25:31', '2026-05-20 05:25:31'),
(40, 'volumetric-calculator', 'testimonials', NULL, NULL, NULL, 'public/website_images/review-1.png', NULL, NULL, '{\"stars\":\"\\u2605\\u2605\\u2605\\u2605\\u2605\",\"text\":\"Very reliable logistics partner with consistent performance, ensuring all my shipments arrive safely, securely, and always on time without any issues.\",\"name\":\"Shelly Kapoor\"}', NULL, 8, 1, '2026-05-20 05:25:31', '2026-05-20 05:25:31'),
(41, 'volumetric-calculator', 'testimonials', NULL, NULL, NULL, 'public/website_images/review-2.png', NULL, NULL, '{\"stars\":\"\\u2605\\u2605\\u2605\\u2605\\u2605\",\"text\":\"Customer support team is highly responsive and helpful, assisting me in tracking my urgent shipment with accurate real-time updates and guidance.\",\"name\":\"Vansh Agarwal\"}', NULL, 9, 1, '2026-05-20 05:25:31', '2026-05-20 05:25:31'),
(42, 'volumetric-calculator', 'testimonials', NULL, NULL, NULL, 'public/website_images/review-3.png', NULL, NULL, '{\"stars\":\"\\u2605\\u2605\\u2605\\u2605\\u2605\",\"text\":\"Best courier service for international deliveries, offering smooth documentation, fast processing, and quick dispatch with no delays or complications.\",\"name\":\"Rahul Mehta\"}', NULL, 10, 1, '2026-05-20 05:25:31', '2026-05-20 05:25:31'),
(43, 'volumetric-calculator', 'testimonials', NULL, NULL, NULL, 'public/website_images/review-4.png', NULL, NULL, '{\"stars\":\"\\u2605\\u2605\\u2605\\u2605\\u2605\",\"text\":\"Affordable pricing combined with premium quality service makes United Worldwide Couriers a highly recommended choice for all shipping and logistics needs.\",\"name\":\"Anjali Sharma\"}', NULL, 11, 1, '2026-05-20 05:25:31', '2026-05-20 05:25:31'),
(44, 'volumetric-calculator', 'testimonials', NULL, NULL, NULL, 'public/website_images/review-5.png', NULL, NULL, '{\"stars\":\"\\u2605\\u2605\\u2605\\u2605\\u2605\",\"text\":\"Professional and efficient team handled my bulk shipments perfectly, ensuring timely delivery, careful handling, and a completely hassle-free logistics experience.\",\"name\":\"Karan Singh\"}', NULL, 12, 1, '2026-05-20 05:25:31', '2026-05-20 05:25:31'),
(45, 'volumetric-calculator', 'faq_sidebar', 'Need personalized help?', 'Our logistics experts are available 24/7 to assist your requirements.', NULL, 'https://i.pinimg.com/originals/f6/5d/46/f65d4681649d85bc91c86872a1775919.gif', NULL, 'Message Support', '{\"illustration_alt\":\"Help\",\"contact_title\":\"Contact Us\",\"contact_description\":\"For urgent inquiries regarding your current shipment status.\"}', NULL, 13, 1, '2026-05-20 05:25:31', '2026-05-20 05:25:31'),
(46, 'volumetric-calculator', 'faq', NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"How do I get started?\",\"answer\":\"To connect with our team, you have to register yourself, get a quote, and schedule your first pickup. Thereafter, the team will guide you through every step of the process.\"}', NULL, 14, 1, '2026-05-20 05:25:31', '2026-05-20 05:25:31'),
(47, 'volumetric-calculator', 'faq', NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"How does United Worldwide Couriers meet your shipping and logistics needs?\",\"answer\":\"To provide the best freight management solutions, we work with broad strategies, technologies, and services to simplify the planning, storage, and movement of goods.\"}', NULL, 15, 1, '2026-05-20 05:25:31', '2026-05-20 05:25:31'),
(48, 'volumetric-calculator', 'faq', NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"What packaging standards should we follow for shipping?\",\"answer\":\"We utilize study and secure packaging for small to large packages to protect your goods during transit. In case of fragile items, they will be cushioned enough and clearly labelled as \\\"Fragile\\\". In addition, we also provide a packaging and labelling guide for all new on boarders for no confusion and faster results.\"}', NULL, 16, 1, '2026-05-20 05:25:31', '2026-05-20 05:25:31'),
(49, 'volumetric-calculator', 'faq', NULL, NULL, NULL, NULL, NULL, NULL, '{\"question\":\"How do we calculate cost?\",\"answer\":\"Our pricing is transparent and competitive. We calculate costs based on package weight, dimensions, destination, and service type. Use our volumetric calculator to estimate dimensional weight.\"}', NULL, 17, 1, '2026-05-20 05:25:31', '2026-05-20 05:25:31'),
(50, 'volumetric-calculator', 'calculator', NULL, NULL, NULL, NULL, NULL, NULL, '{\"divisor_options\":[{\"value\":\"5000\",\"text\":\"5000 Air\",\"width\":\"105px\"},{\"value\":\"400\",\"text\":\"400 Express\",\"width\":\"145px\"},{\"value\":\"6000\",\"text\":\"6000 Sea\",\"width\":\"135px\"}]}', NULL, 18, 1, '2026-05-20 05:25:31', '2026-05-20 05:25:31'),
(51, 'volumetric-calculator', 'hero', 'Weight Calculator', 'Enter your package dimensions to instantly calculate dimensional weight and understand how carriers determine your chargeable weight.', NULL, NULL, NULL, 'Calculate Now', '{\"badge_text\":\"Free Tool \\u00b7 Instant Results\",\"button_url\":\"#calculator\"}', NULL, 1, 1, '2026-05-20 05:32:14', '2026-05-20 05:32:14'),
(52, 'volumetric-calculator', 'features_header', 'Understanding volumetric weights', 'Your package dimensions determine the shipping cost. Here\'s exactly how carriers calculate what you\'ll actually pay.', NULL, NULL, NULL, NULL, NULL, '{\"title\":\"Understanding volumetric weights\",\"description\":\"Your package dimensions determine the shipping cost. Here\'s exactly how carriers calculate what you\'ll actually pay.\"}', 2, 1, '2026-05-20 05:32:14', '2026-05-30 12:09:16'),
(56, 'volumetric-calculator', 'track_cta', 'Track any shipment in real-time', 'Get live updates across all major carriers — end-to-end visibility from pickup to delivery for every order you export worldwide.', NULL, NULL, NULL, 'Track Shipment →', '{\"live_badge\":\"\\u25cf LIVE TRACKING\"}', NULL, 6, 1, '2026-05-20 05:32:14', '2026-05-20 05:32:14'),
(57, 'volumetric-calculator', 'testimonials_header', 'Trusted by the Brands You Trust', 'Join our growing network of satisfied clients who depend on us for easy, secure, fast, and efficient logistics solutions. More than three decades (30+ years) of our positive track record speaks for itself. From on-time delivery and zero-compromise on quality to customer satisfaction, United Worldwide Couriers is completely reliable and trustworthy.', NULL, NULL, NULL, NULL, '{\"badge_url\":\"#\",\"badge_image\":\"public\\/website_images\\/google-review.png\",\"badge_alt\":\"Google\"}', NULL, 7, 1, '2026-05-20 05:32:14', '2026-05-20 05:32:14'),
