INSERT INTO `warehousing_solutions_page` (`id`, `section`, `item_key`, `content`, `icon_svg`, `icon_class`, `color_scheme`, `badge_text`, `button_text`, `button_url`, `btn_text`, `subtitle`, `paragraphs`, `question`, `answer`, `name`, `avatar_url`, `rating`, `text_content`, `stat_value`, `stat_label`, `stat_suffix`, `logo_url`, `alt_text`, `list_items_text`, `check_list_text`, `extra_content`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'hero', 'hero_mains', '{\"title\":\"Your Goods. Our Responsibility.\",\"subtitle\":\"Secure Storage for Your Business Needs\",\"paragraphs\":\"Beyond basic warehousing, we work with advanced inventory systems, security monitoring, and infrastructure made for businesses to stock their shipments safely .\",\"badge_text\":\"Premium Storage\",\"button_text\":\"Get Started\",\"button_url\":\"\\/contact-us\",\"image\":\"images\\/warehousing.webp\",\"list_items\":[\"24\\u201372 Hr Delivery\",\"Fully Insured\",\"220+ Countries\"]}', NULL, NULL, NULL, 'Premium Storage', 'Get Started', '/contact-us', NULL, 'Secure Storage for Your Business Needs', 'Beyond basic warehousing, we work with advanced inventory systems, security monitoring, and infrastructure made for businesses to stock their shipments safely .', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '24–72 Hr Delivery\nFully Insured\n220+ Countries', NULL, '{\"title\":\"Warehousings Solutions\",\"image\":\"images\\/warehousing.webp\"}', 1, 1, '2026-05-13 22:11:13', '2026-05-30 00:47:50'),
(2, 'stats', 'stat_1', '{\"stat_number\":\"50\",\"stat_label\":\"50\",\"suffix\":\"+\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '150', 'Cities Covered', '+', NULL, NULL, NULL, NULL, NULL, 6, 1, '2026-05-13 22:11:13', '2026-05-30 03:54:19'),
(3, 'stats', 'stat_2', '{\"stat_number\":\"100\",\"stat_label\":\"Daily Parcels\",\"suffix\":\"K+\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '100', 'Daily Parcels', 'K+', NULL, NULL, NULL, NULL, NULL, 7, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(4, 'stats', 'stat_3', '{\"stat_number\":\"5\",\"stat_label\":\"Delivery Riders\",\"suffix\":\"K+\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '5', 'Delivery Riders', 'K+', NULL, NULL, NULL, NULL, NULL, 8, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(5, 'stats', 'stat_4', '{\"stat_number\":\"99\",\"stat_label\":\"On-time Rate\",\"suffix\":\".9%\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '99', 'On-time Rate', '.9%', NULL, NULL, NULL, NULL, NULL, 9, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(6, 'stats', 'stat_5', '{\"stat_number\":\"50\",\"stat_label\":\"50\",\"suffix\":\"\\/7\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '24', 'Live Tracking', '/7', NULL, NULL, NULL, NULL, NULL, 10, 1, '2026-05-13 22:11:13', '2026-05-30 03:54:19'),
(7, 'stats', 'stat_6', '{\"stat_number\":\"50\",\"stat_label\":\"Happy Clients\",\"suffix\":\"K+\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '50', 'Happy Clients', 'K+', NULL, NULL, NULL, NULL, NULL, 11, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(8, 'overview', 'overview_main', '{\"title\":\"Store - Track - Ship - Repeat\",\"paragraphs\":\"Take control of your entire supply chain with our warehousing solutions. Businesses can keep the inventory in secure spaces with professional oversight on the packages. Ship with confidence knowing your goods are organized and accessible 24\\/7. We provide fulfilment services and access to your inventory management to have full control over your products.\",\"image\":\"images\\/map-pattern.png\",\"list_items\":[\"Priority loading on partner airline networks across 6 continents\",\"Full customs brokerage with pre-clearance documentation support\",\"Dedicated account manager and 24\\/7 live shipment support\",\"Door-to-door delivery with real-time GPS tracking portal\",\"Fulfilment services\",\"returns management\",\"and COD options\"],\"button_text\":\"Start shipping\",\"button_url\":\"#\"}', NULL, NULL, NULL, NULL, 'Book Shipments', '#', NULL, NULL, 'United Worldwide Couriers offers an exceptional Express Air Freight service built for B2B enterprises, e-commerce businesses, and time-critical international shipments. We operate an end-to-end ecosystem from collection to customs clearance to last-mile delivery all under one roof. Our services span air freight to over 220 countries, including door-to-door personal import pickups and full freight-forwarding with seamless documentation. Each shipment is handled by a dedicated logistics specialist and backed by real-time tracking.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Priority loading on partner airline networks across 6 continents\nFull customs brokerage with pre-clearance documentation support\nDedicated account manager and 24/7 live shipment support\nDoor-to-door delivery with real-time GPS tracking portal\nFulfilment services, returns management, and COD options', NULL, '{\"title\":\"Store. Manage. Fulfil\\u2014Smarter from The USA\",\"image\":\"images\\/map-pattern.png\"}', 12, 1, '2026-05-13 22:11:13', '2026-05-30 03:54:19'),
(9, 'features', 'features_header', '{\"title\":\"Transforming Inventory Management Into Your Advantage\",\"subtitle\":\"Powering your business with cutting-edge logistics technology and unmatched service quality.\",\"description\":\"sss\",\"paragraphs\":\"Every feature is designed to give your business a competitive edge \\u2014 speed, transparency, and reliability, every single shipment. Join our growing network of satisfied clients who depend on us for easy, secure, fast, and efficient logistics solutions. More than three decades (30+ years) of our positive track record speaks for itself.\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Powering your business with cutting-edge logistics technology and unmatched service quality.', 'Every feature is designed to give your business a competitive edge — speed, transparency, and reliability, every single shipment. Join our growing network of satisfied clients who depend on us for easy, secure, fast, and efficient logistics solutions. More than three decades (30+ years) of our positive track record speaks for itself.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"title\":\"What Makes Our E-commerce Logistics Stand Out\"}', 13, 1, '2026-05-13 22:11:13', '2026-05-30 04:15:53'),
(10, 'features', 'feature_tracking', '{\"subtitle\":\"Quality Assurance Protocols\",\"paragraphs\":\"With regular inspections, damage assessments, and compliance checks, we maintain the condition of goods from storage to shipment.\",\"icon_svg\":\"<i class=\\\"fas fa-satellite\\\"><\\/i>\",\"icon_class\":\"fi-blue\"}', '<i class=\"fas fa-satellite\"></i>', 'fi-blue', NULL, NULL, NULL, NULL, NULL, 'Real-Time Tracking', 'Monitor your shipment at every checkpoint — from pickup to customs to final-mile — through our live dashboard and SMS alerts.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 14, 1, '2026-05-13 22:11:13', '2026-05-30 04:12:31'),
(11, 'features', 'feature_temperature', '{\"subtitle\":\"Automated Stock Optimization\",\"paragraphs\":\"Control overstock and stockouts with smart demand-based inventory management.\",\"icon_svg\":\"<i class=\\\"fas fa-thermometer-half\\\"><\\/i>\",\"icon_class\":\"fi-orange\"}', '<i class=\"fas fa-thermometer-half\"></i>', 'fi-orange', NULL, NULL, NULL, NULL, NULL, 'Automated Stock Optimization', 'Control overstock and stockouts with smart demand-based inventory management.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 15, 1, '2026-05-13 22:11:13', '2026-05-30 04:13:25'),
(12, 'features', 'feature_support', '{\"subtitle\":\"Monitoring and Security\",\"paragraphs\":\"24\\/7 surveillance and security systems ensure goods are protected from damage, theft, or loss.\",\"icon_svg\":\"<i class=\\\"fas fa-headset\\\"><\\/i>\",\"icon_class\":\"fi-navy\"}', '<i class=\"fas fa-headset\"></i>', 'fi-navy', NULL, NULL, NULL, NULL, NULL, 'Monitoring and Security', '24/7 surveillance and security systems ensure goods are protected from damage, theft, or loss.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 16, 1, '2026-05-13 22:11:13', '2026-05-30 04:14:43'),
(13, 'features', 'feature_eco', '{\"subtitle\":\"Multi-Channel Inclusion\",\"paragraphs\":\"Businesses can manage their inventory for all channels like B2B, D2C and e-commerce.\",\"icon_svg\":\"<i class=\\\"fas fa-leaf\\\"><\\/i>\",\"icon_class\":\"fi-green\"}', '<i class=\"fas fa-leaf\"></i>', 'fi-green', NULL, NULL, NULL, NULL, NULL, 'Multi-Channel Inclusion', 'Businesses can manage their inventory for all channels like B2B, D2C and e-commerce.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 17, 1, '2026-05-13 22:11:13', '2026-05-30 04:15:14'),
(14, 'testimonials', 'testimonials_header', '{\"title\":\"Trusted by the Brands You Trust\",\"paragraphs\":\"Join our growing network of satisfied clients who depend on us for easy, secure, fast, and efficient logistics solutions. More than three decades (30+ years) of our positive track record speaks for itself. From on-time delivery and zero-compromise on quality to customer satisfaction, United Worldwide Couriers is completely reliable and trustworthy.\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Join our growing network of satisfied clients who depend on us for easy, secure, fast, and efficient logistics solutions. More than three decades (30+ years) of our positive track record speaks for itself. From on-time delivery and zero-compromise on quality to customer satisfaction, United Worldwide Couriers is completely reliable and trustworthy.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"title\":\"Trusted by the Brands You Trust\"}', 18, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(15, 'testimonials', 'testimonial_1', '{\"subtitle\":\"Shelly Kapoor\",\"description\":\"Very reliable logistics partner with consistent performance, ensuring all my shipments arrive safely, securely, and always on time without any issues.\",\"image\":\"images\\/review-1.png\",\"rating\":5}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Shelly Kapoor', NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"Very reliable logistics partner with consistent performance, ensuring all my shipments arrive safely, securely, and always on time without any issues.\",\"image\":\"images\\/review-1.png\"}', 19, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(16, 'testimonials', 'testimonial_2', '{\"subtitle\":\"Vansh Agarwal\",\"description\":\"Customer support team is highly responsive and helpful, assisting me in tracking my urgent shipment with accurate real-time updates and guidance.\",\"image\":\"images\\/review-2.png\",\"rating\":5}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Vansh Agarwal', NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"Customer support team is highly responsive and helpful, assisting me in tracking my urgent shipment with accurate real-time updates and guidance.\",\"image\":\"images\\/review-2.png\"}', 20, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(17, 'testimonials', 'testimonial_3', '{\"subtitle\":\"Rahul Mehta\",\"description\":\"Best courier service for international deliveries, offering smooth documentation, fast processing, and quick dispatch with no delays or complications.\",\"image\":\"images\\/review-3.png\",\"rating\":5}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Rahul Mehta', NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"Best courier service for international deliveries, offering smooth documentation, fast processing, and quick dispatch with no delays or complications.\",\"image\":\"images\\/review-3.png\"}', 21, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(18, 'testimonials', 'testimonial_4', '{\"subtitle\":\"Anjali Sharma\",\"description\":\"Affordable pricing combined with premium quality service makes United Worldwide Couriers a highly recommended choice for all shipping and logistics needs.\",\"image\":\"images\\/review-4.png\",\"rating\":5}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Anjali Sharma', NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"Affordable pricing combined with premium quality service makes United Worldwide Couriers a highly recommended choice for all shipping and logistics needs.\",\"image\":\"images\\/review-4.png\"}', 22, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(19, 'testimonials', 'testimonial_5', '{\"quote\":\"chirag\",\"name\":\"chirag\",\"photo\":null,\"rating\":5}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'chirag', NULL, 5.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"quote\":\"chirag\",\"photo\":null}', 23, 1, '2026-05-13 22:11:13', '2026-05-13 23:25:56'),
(20, 'testimonials', 'testimonial_6', '{\"subtitle\":\"Vinay Verma\",\"description\":\"United Worldwide Couriers delivered my international parcel quickly and safely, with smooth handling and excellent service throughout the entire process.\",\"image\":\"images\\/review-5.png\",\"rating\":5}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Vinay Verma', NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"United Worldwide Couriers delivered my international parcel quickly and safely, with smooth handling and excellent service throughout the entire process.\",\"image\":\"images\\/review-5.png\"}', 24, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(21, 'testimonials', 'testimonial_7', '{\"subtitle\":\"Shelly Kapoor\",\"description\":\"Very reliable logistics partner with consistent performance, ensuring all my shipments arrive safely, securely, and always on time without any issues.\",\"image\":\"images\\/review-6.png\",\"rating\":5}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Shelly Kapoor', NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"Very reliable logistics partner with consistent performance, ensuring all my shipments arrive safely, securely, and always on time without any issues.\",\"image\":\"images\\/review-6.png\"}', 25, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(22, 'testimonials', 'testimonial_8', '{\"subtitle\":\"Vansh Agarwal\",\"description\":\"Customer support team is highly responsive and helpful, assisting me in tracking my urgent shipment with accurate real-time updates and guidance.\",\"image\":\"images\\/review-7.png\",\"rating\":5}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Vansh Agarwal', NULL, NULL, NULL, NULL, NULL, 5.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"Customer support team is highly responsive and helpful, assisting me in tracking my urgent shipment with accurate real-time updates and guidance.\",\"image\":\"images\\/review-7.png\"}', 26, 1, '2026-05-13 22:11:13', '2026-05-13 22:11:13'),
(23, 'faq', 'faq_1', '{\"subtitle\":\"How do I get started?\",\"description\":\"To connect with our team, you have to register yourself, get a quote, and schedule your first pickup. Thereafter, the team will guide you through every step of the process.\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'How do I get started?', NULL, 'How do I get started?', 'To connect with our team, you have to register yourself, get a quote, and schedule your first pickup. Thereafter, the team will guide you through every step of the process.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"To connect with our team, you have to register yourself, get a quote, and schedule your first pickup. Thereafter, the team will guide you through every step of the process.\"}', 27, 1, '2026-05-13 22:11:13', '2026-05-20 05:26:13'),
(24, 'faq', 'faq_2', '{\"subtitle\":\"How does United Worldwide Couriers meet your shipping and logistics needs?\",\"description\":\"To provide the best freight management solutions, we work with broad strategies, technologies, and services to simplify the planning, storage, and movement of goods.\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'How does United Worldwide Couriers meet your shipping and logistics needs?', NULL, 'How does United Worldwide Couriers meet your shipping and logistics needs?', 'To provide the best freight management solutions, we work with broad strategies, technologies, and services to simplify the planning, storage, and movement of goods.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"To provide the best freight management solutions, we work with broad strategies, technologies, and services to simplify the planning, storage, and movement of goods.\"}', 28, 1, '2026-05-13 22:11:13', '2026-05-20 05:26:13'),
(25, 'faq', 'faq_3', '{\"subtitle\":\"What packaging standards should we follow for shipping?\",\"description\":\"We utilize study and secure packaging for small to large packages to protect your goods during transit. In case of fragile items, they will be cushioned enough and clearly labelled as \\\"Fragile\\\". In addition, we also provide a packaging and labelling guide for all new on boarders for no confusion and faster results.\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'What packaging standards should we follow for shipping?', NULL, 'What packaging standards should we follow for shipping?', 'We utilize study and secure packaging for small to large packages to protect your goods during transit. In case of fragile items, they will be cushioned enough and clearly labelled as \"Fragile\". In addition, we also provide a packaging and labelling guide for all new on boarders for no confusion and faster results.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"We utilize study and secure packaging for small to large packages to protect your goods during transit. In case of fragile items, they will be cushioned enough and clearly labelled as \\\"Fragile\\\". In addition, we also provide a packaging and labelling guide for all new on boarders for no confusion and faster results.\"}', 29, 1, '2026-05-13 22:11:13', '2026-05-20 05:26:13'),
(26, 'faq', 'faq_4', '{\"subtitle\":\"How do we calculate cost?\",\"description\":\"The exact shipping cost will be calculated based on your goods\' weight, dimensions, destinations, where it is expected to be delivered, and the delivery speed. If you are interested in knowing the accurate pricing, you are welcome to connect with the team.\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'How do we calculate cost?', NULL, 'How do we calculate cost?', 'The exact shipping cost will be calculated based on your goods\' weight, dimensions, destinations, where it is expected to be delivered, and the delivery speed. If you are interested in knowing the accurate pricing, you are welcome to connect with the team.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"The exact shipping cost will be calculated based on your goods\' weight, dimensions, destinations, where it is expected to be delivered, and the delivery speed. If you are interested in knowing the accurate pricing, you are welcome to connect with the team.\"}', 30, 1, '2026-05-13 22:11:13', '2026-05-20 05:26:13'),
(27, 'faq', 'faq_5', '{\"subtitle\":\"Will I be notified about my shipment status?\",\"description\":\"Yes. To keep the clients informed, our team provides regular updates via email or SMS throughout the shipping process.\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Will I be notified about my shipment status?', NULL, 'Will I be notified about my shipment status?', 'Yes. To keep the clients informed, our team provides regular updates via email or SMS throughout the shipping process.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"Yes. To keep the clients informed, our team provides regular updates via email or SMS throughout the shipping process.\"}', 31, 1, '2026-05-13 22:11:13', '2026-05-20 05:26:13'),
(28, 'faq', 'faq_6', '{\"subtitle\":\"Does United Worldwide Couriers handle bulk or commercial shipments?\",\"description\":\"Yes, we specialize in managing bulk as well as commercial consignments with easy-flowing coordination, dedicated handling, secure transit, and timely delivery. This remains the same for both small and large volumes.\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Does United Worldwide Couriers handle bulk or commercial shipments?', NULL, 'Does United Worldwide Couriers handle bulk or commercial shipments?', 'Yes, we specialize in managing bulk as well as commercial consignments with easy-flowing coordination, dedicated handling, secure transit, and timely delivery. This remains the same for both small and large volumes.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"Yes, we specialize in managing bulk as well as commercial consignments with easy-flowing coordination, dedicated handling, secure transit, and timely delivery. This remains the same for both small and large volumes.\"}', 32, 1, '2026-05-13 22:11:13', '2026-05-20 05:26:13'),
(29, 'faq', 'faq_7', '{\"subtitle\":\"Can I schedule a pickup for my shipment?\",\"description\":\"Yes, you can easily schedule a pick up at your preferred time either by reaching out to our team online (via our website) or by directly contacting our customer support.\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Can I schedule a pickup for my shipment?', NULL, 'Can I schedule a pickup for my shipment?', 'Yes, you can easily schedule a pick up at your preferred time either by reaching out to our team online (via our website) or by directly contacting our customer support.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"Yes, you can easily schedule a pick up at your preferred time either by reaching out to our team online (via our website) or by directly contacting our customer support.\"}', 33, 1, '2026-05-13 22:11:13', '2026-05-20 05:26:13'),
(30, 'faq', 'faq_8', '{\"subtitle\":\"How can I track my shipment?\",\"description\":\"Through our online tracking system, you can track your shipment in real-time. For that, you just have to enter the tracking ID provided on our website dashboard to get live updates.\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'How can I track my shipment?', NULL, 'How can I track my shipment?', 'Through our online tracking system, you can track your shipment in real-time. For that, you just have to enter the tracking ID provided on our website dashboard to get live updates.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"Through our online tracking system, you can track your shipment in real-time. For that, you just have to enter the tracking ID provided on our website dashboard to get live updates.\"}', 34, 1, '2026-05-13 22:11:13', '2026-05-20 05:26:13'),
(31, 'faq', 'faq_9', '{\"subtitle\":\"Will my package be picked up by the United Worldwide Couriers team only?\",\"description\":\"It depends on the service and location. So, your shipment may be picked up either by our in-house delivery team or by third-party courier partners. On the contrary, we ensure strict quality control and safe handling for whatever the case may be.\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Will my package be picked up by the United Worldwide Couriers team only?', NULL, 'Will my package be picked up by the United Worldwide Couriers team only?', 'It depends on the service and location. So, your shipment may be picked up either by our in-house delivery team or by third-party courier partners. On the contrary, we ensure strict quality control and safe handling for whatever the case may be.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"It depends on the service and location. So, your shipment may be picked up either by our in-house delivery team or by third-party courier partners. On the contrary, we ensure strict quality control and safe handling for whatever the case may be.\"}', 35, 1, '2026-05-13 22:11:13', '2026-05-20 05:26:13'),
(32, 'faq', 'faq_10', '{\"subtitle\":\"Do you provide customs clearance support?\",\"description\":\"Yes, while others face limited support, we complete international customs documentation and clearance faster. This way, we support rapid shipping without delays.\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Do you provide customs clearance support?', NULL, 'Do you provide customs clearance support?', 'Yes, while others face limited support, we complete international customs documentation and clearance faster. This way, we support rapid shipping without delays.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"Yes, while others face limited support, we complete international customs documentation and clearance faster. This way, we support rapid shipping without delays.\"}', 36, 1, '2026-05-13 22:11:13', '2026-05-20 05:26:13'),
(33, 'faq', 'faq_11', '{\"subtitle\":\"What happens if my shipment is delayed or stuck?\",\"description\":\"First things first, the team proactively monitors the shipment to identify and resolve potential issues before they escalate. Still, if an issue occurs, the internal team coordinates with the partners to resolve the situation quickly.\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'What happens if my shipment is delayed or stuck?', NULL, 'What happens if my shipment is delayed or stuck?', 'First things first, the team proactively monitors the shipment to identify and resolve potential issues before they escalate. Still, if an issue occurs, the internal team coordinates with the partners to resolve the situation quickly.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"description\":\"First things first, the team proactively monitors the shipment to identify and resolve potential issues before they escalate. Still, if an issue occurs, the internal team coordinates with the partners to resolve the situation quickly.\"}', 37, 1, '2026-05-13 22:11:13', '2026-05-20 05:26:13'),
(34, 'cta', 'cta_main', '{\"title\":\"Ready to Optimize Your Storage?\",\"subtitle\":\"Get in touch with our team to discuss your warehousing needs\",\"button_text\":\"Contact Us\",\"button_url\":\"\\/contact-us\"}', NULL, NULL, NULL, NULL, 'Contact Us', '/contact-us', NULL, 'Get in touch with our team to discuss your warehousing needs', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"title\":\"Ready to Optimize Your Storage?\",\"subtitle\":\"Get in touch with our team to discuss your warehousing needs\"}', 38, 1, '2026-05-13 22:11:13', '2026-05-30 03:54:19'),
(36, 'hero', 'hero_main', NULL, NULL, NULL, NULL, 'Premium Storage', 'Get Started', '/contact-us', NULL, 'Secure Storage for Your Business Needs', 'Our state-of-the-art warehousing facilities provide secure, climate-controlled storage solutions tailored to your business requirements. With advanced inventory management systems and 24/7 monitoring, we ensure your goods are safe and accessible whenever you need them.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '24–72 Hr Delivery\nFully Insured\n220+ Countries', NULL, '{\"title\":\"Warehousing Solutions\",\"image\":\"images\\/warehousing.webp\"}', 1, 1, '2026-05-30 03:54:19', '2026-05-30 03:54:19');
